#include <stdio.h>

int main() {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);
    char pattern[505];
    scanf("%s", pattern);

    char choices[500][27];
    int len[500];

    for (int i = 0; i < M; i++) {
        char word[30];
        scanf("%s", word);
        int present[26] = {0};
        for (int j = 0; j < K; j++) {
            present[word[j] - 'a'] = 1;
        }
        int cnt = 0;
        for (int c = 0; c < 26; c++) {
            if (present[c]) {
                choices[i][cnt++] = 'a' + c;
            }
        }
        len[i] = cnt;
    }

    long long P;
    scanf("%lld", &P);

    const long long CAP = 1000000001LL;
    long long ways[501];
    ways[M] = 1;

    for (int i = M - 1; i >= 0; i--) {
        long long prod = ways[i + 1] * len[i];
        if (prod > CAP) prod = CAP;
        ways[i] = prod;
    }

    char chosen[500];
    for (int i = 0; i < M; i++) {
        long long count = ways[i + 1];
        for (int j = 0; j < len[i]; j++) {
            if (P > count) {
                P -= count;
            } else {
                chosen[i] = choices[i][j];
                break;
            }
        }
    }

    char result[505];
    int idx = 0;
    for (int i = 0; i < N; i++) {
        if (pattern[i] == '#') {
            result[i] = chosen[idx++];
        } else {
            result[i] = pattern[i];
        }
    }
    result[N] = '\0';

    printf("%s\n", result);
    return 0;
}
